      twitter: { card: "summary_large_image", title: "Google Ads vs Meta Ads: Which Is Better?", description: "Practical comparison to help you choose the right advertising platform.", image: "/images/blogs/2. Google Ads vs Meta Ads Which Is Better for Your Business.png" },
