    seo: { title: "WhatsApp Marketing Strategy for Local Businesses | KlickChamp", description: "Complete guide to WhatsApp marketing for Indian businesses. Setup, broadcast lists, catalogs, and communication strategies.", canonical: "https://klickchamp.com/blog/whatsapp-marketing-local-businesses", openGraph: { title: "WhatsApp Marketing Strategy for Local Businesses", description: "How to use WhatsApp Business to reach local customers and drive sales.", type: "article", image: "/images/blogs/WhatsApp Marketing Strategy for Local Businesses in India.png" }, twitter: { card: "summary_large_image", title: "WhatsApp Marketing Strategy for Local Businesses", description: "How to use WhatsApp Business to reach local customers and drive sales.", image: "/images/blogs/WhatsApp Marketing Strategy for Local Businesses in India.png" },       schemas: [] },
