/* ------------------------------------------------------------------ */
/*  Adjacent posts (prev / next by date)                               */
/* ------------------------------------------------------------------ */

export interface AdjacentPost {
  slug: string;
  title: string;
}

export function getAdjacentPosts(slug: string): { prev: AdjacentPost | null; next: AdjacentPost | null } {
  const sorted = [...BLOG_POSTS].sort(
    (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
  );
  const idx = sorted.findIndex((p) => p.slug === slug);
  if (idx === -1) return { prev: null, next: null };

  const prev = idx < sorted.length - 1
    ? { slug: sorted[idx + 1].slug, title: sorted[idx + 1].title }
    : null;
  const next = idx > 0
    ? { slug: sorted[idx - 1].slug, title: sorted[idx - 1].title }
    : null;

  return { prev, next };
}

export function getBlogCategoryTitle(categoryId: string): string {
  const cat = BLOG_CATEGORIES.find((c) => c.id === categoryId);
  return cat ? cat.title : categoryId;
}
